CREATE     VIEW [CE].[vwRics_Route]
AS 

WITH cteRoute AS
(
	SELECT tab.Application_Type, tab.Route_Name FROM(VALUES
		('Recognised Professional Qualification', '(AIC) Appraisal Institute of Canada/Institut Canadien des Evaluateurs'),
		('Recognised Professional Qualification', 'AACI Appraisal Instutite of Canada'),
		('Recognised Professional Qualification', 'ACLS Association of Canada Lands Surveyors'),
		('Recognised Professional Qualification', 'AICPA America Institute of Certified Public Accountants'),
		('Recognised Professional Qualification', 'AIQS Australia Institute of QS'),
		('Recognised Professional Qualification', 'ANEVAR Asociatia Nationala a Evaluatorilor di'),
		('Recognised Professional Qualification', 'API Australian Property Institute'),
		('Recognised Professional Qualification', 'ASA American Society of Appraisers'),
		('Recognised Professional Qualification', 'ASPECT'),
		('Recognised Professional Qualification', 'Aspect (SFF)'),
		('Recognised Professional Qualification', 'BSIJ Building Surveyor''s Institute of Japan'),
		('Recognised Professional Qualification', 'Category A - Hydrography'),
		('Recognised Professional Qualification', 'CCIM Certified Commercial Investment Member In'),
		('Recognised Professional Qualification', 'CFAI Chartered Financial Analyst Institute'),
		('Recognised Professional Qualification', 'Chartered Recognised Professional Qualification'),
		('Recognised Professional Qualification', 'China International Contractors Association'),
		('Recognised Professional Qualification', 'CIQS Canadian Institute of Quantity Surveyors'),
		('Recognised Professional Qualification', 'CLSS China Land Science Society'),
		('Recognised Professional Qualification', 'CRE Counselors of Real Estate'),
		('Recognised Professional Qualification', 'CRRPA - United States Appraisal Foundation'),
		('Recognised Professional Qualification', 'GhIS Ghana Institution of Surveyors'),
		('Recognised Professional Qualification', 'HKIH - Hong Kong Institute of Housing'),
		('Recognised Professional Qualification', 'HKIS Hong Kong Institute of Surveyors'),
		('Recognised Professional Qualification', 'HypZert (F) valuers'),
		('Recognised Professional Qualification', 'HypZert (MLV) valuers'),
		('Recognised Professional Qualification', 'ICES Chartered Institution of Civil Engineering Surveyors'),
		('Recognised Professional Qualification', 'ICF - Institute of Chartered Foresters'),
		('Recognised Professional Qualification', 'IPREA - Institute of Philippines Real Estate Appraisers'),
		('Recognised Professional Qualification', 'IQSK Institute of Quantity Surveyors of Kenya'),
		('Recognised Professional Qualification', 'IQSSL - Institute of QS Sri Lanka'),
		('Recognised Professional Qualification', 'IQSSL Institute of Quantity Surveyors, Sri Lanka - Associate Member'),
		('Recognised Professional Qualification', 'Level 1 Building Certifier'),
		('Recognised Professional Qualification', 'MAI Member of Appraisal Institute'),
		('Recognised Professional Qualification', 'NZIQS - New Zealand Institute of Quantity Surveyors'),
		('Recognised Professional Qualification', 'NZIS New Zealand Institute of Surveyors'),
		('Recognised Professional Qualification', 'OPA - Oberprufungsamt des Bundes'),
		('Recognised Professional Qualification', 'PINZ Property Institute of New Zealand'),
		('Recognised Professional Qualification', 'RISM Royal Institution of Surveyors Malaysia'),
		('Recognised Professional Qualification', 'SACPCMP South African Council for the Project and Construction Management Professions'),
		('Recognised Professional Qualification', 'SACPVP South African Council for the Property Profession'),
		('Recognised Professional Qualification', 'SACQSP - South African Council for the Quantity Surveying Profession'),
		('Recognised Professional Qualification', 'SAGC South African Geomatics Council (prev PLATO)'),
		('Recognised Professional Qualification', 'SCS Society of Chartered Surveyors in Ireland'),
		('Recognised Professional Qualification', 'SISV Singapore Institute of Surveyors and Valuers'),
		('Recognised Professional Qualification', 'TAQEEM Saudi Authority for Accredited Valuers (Fellow)'),
		('Recognised Professional Qualification', 'VRBNZ Valuers Registration Board of New Zealand'),
		('Recognised Professional Qualification', 'Associate RPQ'),
		('Recognised Professional Qualification', 'Chartered RPQ'),

		('Assessment', 'Academic'),
		('Assessment', 'APC Other'),
		('Assessment', 'APC Prelim'),
		('Assessment', 'APC Structured Training 12'),
		('Assessment', 'APC Structured Training 24'),
		('Assessment', 'Associate Assessment'),
		('Assessment', 'Associate Recognised Professional Qualification'),
		('Assessment', 'Fellowship By Application'),
		('Assessment', 'Senior Professional Assessment - July 2017'),
		('Assessment', 'Specialist Assessment')
	) tab (Application_Type, Route_Name)

)
SELECT 
	rt.[Rics_routeId],
	rt.[Rics_name],
	rt.[CreatedBy],
	rt.[CreatedByName],
	rt.[Created_On],
	rt.[ModifiedBy],
	rt.[ModifiedByName],
	rt.[Modified_On],
	rt.[ricsv2_EnrolmentTypeId],
	rt.[ricsv2_EnrolmentTypeIdName],
	rt.[rics_applicationtypeid],
	rt.[rics_applicationtypeidName],
	rt.[ImportSequenceNumber],
	rt.[OverriddenCreatedOn],
	rt.[statecode],
	rt.[StateCode_Description],
	rt.[statuscode],
	rt.[StatusCode_Description],
	c1.[Application_Type]
FROM [synapse_ce].[vwRics_Route] rt
	LEFT JOIN cteRoute c1
		ON rt.[Rics_name] = c1.[Route_Name]
